package dev.todotracker.core.vault

import java.io.File
import java.time.Instant
import java.time.ZoneOffset
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive

/** The shared fixtures in tests/fixtures (generated by the C# core), as every port reads them. */
object Fixtures {
    val dir: File by lazy {
        var d: File? = File("").absoluteFile
        while (d != null) {
            val candidate = File(d, "tests/fixtures")
            if (candidate.isDirectory) return@lazy candidate
            d = d.parentFile
        }
        error("tests/fixtures not found")
    }

    fun read(relative: String): JsonObject = Json.parseToJsonElement(File(dir, relative).readText()).jsonObject

    /** The fixed zone and "now" of the vault fixtures (UTC−05:00, 2026-01-05T14:00Z). */
    val zone: ZoneOffset = ZoneOffset.ofHours(-5)
    val now: Instant = Instant.parse("2026-01-05T14:00:00Z")

    fun context(path: String): TaskMarkdownContext {
        val slash = path.lastIndexOf('/')
        return TaskMarkdownContext(zone, now, if (slash < 0) "" else path.substring(0, slash), path)
    }
}

fun JsonElement?.s(): String? = (this as? JsonPrimitive)?.takeIf { it.isString }?.content

fun JsonObject.s(key: String): String = this[key]!!.jsonPrimitive.content

fun JsonObject.arr(key: String): JsonArray = this[key]!!.jsonArray

fun JsonObject.obj(key: String): JsonObject = this[key]!!.jsonObject
